export const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

/** v2.8: snap a legacy slider value to the nearest segment step (settings sliders → segments). */
export function nearest(values, target) {
  let best = values[0];
  for (const v of values) if (Math.abs(v - target) < Math.abs(best - target)) best = v;
  return best;
}

